  const burmeseLessonContent: Record<string, Lesson> = {
    introduction: { intro: "Zap သည် .zp source file များကို အသုံးပြုသော ဖတ်ရလွယ်သည့် general-purpose programming language ဖြစ်သည်။ သင်ခန်းစာတစ်ခုစီတွင် အယူအဆတစ်ခုကို နားလည်ပြီး code တစ်ခုကို run လုပ်ကာ နောက်သင်ခန်းစာသို့ ဆက်သွားပါ။", blocks: [["Zap ၏ အခြေခံအမြင်", "Program သည် အပေါ်မှအောက်သို့ အစဉ်လိုက် run သည့် statement များဖြစ်သည်။ Block များကို colon နှင့် indentation ဖြင့် ဖော်ပြသည်။", "say \"Hello from Zap\""], ["ပထမဆုံးလေ့ကျင့်ခန်း", "hello.zp ဖိုင်ဖန်တီးပြီး message ကို ကိုယ်တိုင်ပြောင်းပါ။ Output ပြောင်းသွားပါက ပထမဆုံး feedback loop ကို ပြီးမြောက်ပါပြီ။", "zap hello.zp"]] },
    installation: { intro: "Zap ကို native executable အဖြစ် download လုပ်ပြီး PATH ထဲထည့်ပါ။ သင့် operating system နှင့် architecture ကိုက်ညီသော official release asset ကိုသာ ရွေးပါ။", blocks: [["Version စစ်ခြင်း", "Install ပြီးနောက် runtime နှင့် help output ကို စစ်ပါ။", "zap --version\nzap --help"], ["Release ကို အသုံးပြုခြင်း", "Linux၊ Windows နှင့် macOS အတွက် official release archive များကို GitHub Releases မှ ရယူနိုင်သည်။ မိမိထည့်သွင်းထားသော version နှင့် docs version မတူပါက example behavior ကို ပြန်စစ်ပါ။"]] },
    "quick-start": { intro: "Zap ကို စတင်လေ့လာရန် .zp ဖိုင်တစ်ခုထဲတွင် say statement ရေးပြီး CLI ဖြင့် run လုပ်ပါ။ Boilerplate မလိုအပ်ပါ။", blocks: [["ပထမဆုံး program", "Program သည် line တစ်ကြောင်းမှ စနိုင်သည်။ say သည် terminal တွင် value ကို ထုတ်ပြသည်။", "say \"မင်္ဂလာပါ Zap\""], ["Run၊ check၊ test", "Project ကြီးလာသောအခါ init ဖြင့် scaffold ဖန်တီးပြီး check၊ fmt နှင့် test ဖြင့် feedback ရယူပါ။", "zap init my-project\nzap check .\nzap fmt main.zp\nzap test ."]] },
    syntax: { intro: "Zap syntax တွင် comment ကို # ဖြင့်ရေးပြီး block ကို colon နောက်မှ indentation ဖြင့်ရေးသည်။ Indentation တစ်ဆင့်လျှင် spaces လေးခုကို အကြံပြုသည်။", blocks: [["Variables နှင့် values", "Variable အသစ်ကို let ဖြင့်ဖန်တီးပြီး ရှိပြီးသား value ကို assignment ဖြင့်ပြောင်းပါ။", "let name = \"Zap\"\nlet count: number = 3\ncount = count + 1"], ["စစ်ဆေးပြီးမှ run ပါ", "zap check . သည် syntax၊ name နှင့် type ပြဿနာများကို run မလုပ်မီ ပြပေးသည်။", "zap check .\nzap check --json ."]] },
    "control-flow": { intro: "Condition နှင့် loop များက program ကို ဆုံးဖြတ်ချက်ချစေပြီး အလုပ်များကို ပြန်လုပ်စေသည်။ if၊ else၊ for နှင့် while ကို colon နှင့် indentation ဖြင့် အသုံးပြုပါ။", blocks: [["If နှင့် else", "Condition မှန်လျှင် if block ကို run ပြီး မမှန်လျှင် else block ကို run သည်။", "let score = 85\nif score >= 80:\n    say \"အောင်မြင်သည်\"\nelse:\n    say \"ထပ်လေ့ကျင့်ပါ\""], ["Loop များ", "for သည် list သို့ range တစ်ခုကို လှည့်ပြီး while သည် condition မှန်နေသရွေ့ ပြန်လုပ်သည်။ Loop ထဲတွင် state ကို update မလုပ်ပါက မရပ်နိုင်ပါ။", "for item in [\"web\", \"ai\"]:\n    say item"]] },
    functions: { intro: "Function သည် code block တစ်ခုကို နာမည်ပေးပြီး ပြန်လည်အသုံးပြုစေသည်။ Parameter၊ return value၊ local scope နှင့် nested function များကို အသုံးပြုနိုင်သည်။", blocks: [["Function ရေးခြင်း", "fn ဖြင့် function တည်ဆောက်ပြီး return ဖြင့် result ပြန်ပေးပါ။", "fn add(a, b):\n    return a + b\n\nsay add(4, 6)"], ["လက်တွေ့လေ့ကျင့်ခန်း", "Number တစ်ခု even ဖြစ်မဖြစ် boolean ပြန်ပေးသည့် is_even function ရေးပါ။ ထို့နောက် 0၊ even နှင့် odd တန်ဖိုးများဖြင့် စမ်းပါ။"]] },
    types: { intro: "Zap တွင် text၊ number၊ bool၊ list၊ map၊ none နှင့် any တို့သည် အခြေခံ type များဖြစ်သည်။ Annotation သည် value တစ်ခု၏ မျှော်မှန်းထားသော type ကို ရှင်းလင်းစေသည်။", blocks: [["အခြေခံ types", "String ကို text၊ ကိန်းဂဏန်းကို number၊ true/false ကို bool၊ အစဉ်လိုက်တန်ဖိုးများကို list၊ key/value record ကို map အဖြစ် အသုံးပြုပါ။", "let title: text = \"Zap\"\nlet count: number = 3\nlet ready: bool = true"], ["Result နှင့် Option", "Result သည် အောင်မြင်မှု သို့မဟုတ် အမှားကို ကိုယ်စားပြုပြီး Option သည် value ရှိ/မရှိကို ကိုယ်စားပြုသည်။", "let answer: result<number> = ok(42)\nlet missing: option<text> = option_none()"]] },
    modules: { intro: "Module များသည် project ကို စနစ်တကျခွဲပေးပြီး export မလုပ်ထားသော private helper များကို အပြင်မှ မမြင်ရစေပါ။", blocks: [["Module နှင့် import", "Logical name ကို module ဖြင့်သတ်မှတ်ပြီး dotted path နှင့် alias ဖြင့် import လုပ်ပါ။", "module app.core\n\nexport fn greet(name):\n    return \"Hello, \" + name\n\nmodule app.main\nimport app.core as core\nsay core.greet(\"Zap\")"], ["လုံခြုံရေးစည်းမျဉ်း", "Absolute path၊ traversal-like path၊ missing entry၊ duplicate entry နှင့် circular import များကို runtime က reject လုပ်သည်။"]] },
    "stdlib-text": { intro: "Text standard library သည် စာသားများကို စစ်ဆေးခြင်း၊ whitespace ဖယ်ခြင်း၊ ခွဲခြင်းနှင့် ပြန်လည်ပေါင်းစည်းခြင်းတို့အတွက် အသုံးပြုသည်။", blocks: [["Text ကို စစ်ဆေးခြင်း", "len နှင့် type ကို အသုံးပြုပြီး value ၏ အရွယ်အစားနှင့် type ကို စစ်ပါ။", "let name = \"  Zap  \"\nsay len(name)\nsay type(name)"], ["Text သန့်ရှင်းခြင်း", "trim ဖြင့် အစနှင့်အဆုံး whitespace ဖယ်ပြီး upper/lower ဖြင့် စာလုံးအကြီးအသေး ပြောင်းနိုင်သည်။", "let clean = trim(\"  Zap Language  \")\nsay upper(clean)\nsay split(clean, \" \")"], ["လေ့ကျင့်ခန်း", "စာကြောင်းတစ်ကြောင်းကို trim လုပ်၊ words များအဖြစ် split လုပ်ပြီး comma ဖြင့် join လုပ်ပါ။"]] },
    "stdlib-math": { intro: "Math helpers များသည် အခြေခံကိန်းဂဏန်းတွက်ချက်မှုများကို function အသစ်မရေးဘဲ အသုံးပြုနိုင်စေသည်။", blocks: [["အခြေခံ math helpers", "abs သည် အကြွင်းမဲ့တန်ဖိုး၊ min သည် အငယ်ဆုံး၊ max သည် အကြီးဆုံးတန်ဖိုးကို ပြန်ပေးသည်။", "say abs(-8)\nsay min(4, 9)\nsay max(4, 9)"], ["Power နှင့် square root", "pow ဖြင့် power တွက်ပြီး sqrt ဖြင့် square root တွက်နိုင်သည်။", "say pow(2, 3)\nsay sqrt(81)"], ["လေ့ကျင့်ခန်း", "Score နှစ်ခုကြား absolute difference၊ အငယ်ဆုံး score နှင့် အကြီးဆုံး score ကို output ပြပါ။"]] },
    "stdlib-collections": { intro: "Collection helpers များသည် list နှင့် map များကို ဖတ်ရလွယ်အောင် စစ်ဆေး၊ ရှာဖွေ၊ စီစဉ်နှင့် စုစည်းနိုင်စေသည်။", blocks: [["List စစ်ဆေးခြင်း", "len နှင့် is_empty ဖြင့် list အခြေအနေကို စစ်ပြီးမှ index အသုံးပြုပါ။ Index သည် 0 မှ စသည်။", "let items = [\"web\", \"ai\"]\nsay len(items)\nsay is_empty(items)"], ["Map lookup", "keys၊ contains နှင့် get ဖြင့် key ရှိ/မရှိကို လုံခြုံစွာ စစ်ပါ။", "let user = {\"name\": \"Mya\"}\nsay keys(user)\nsay contains(user, \"name\")\nsay get(user, \"name\")"], ["လေ့ကျင့်ခန်း", "Number သုံးခုပါသော list တစ်ခုကို sort၊ reverse လုပ်ပြီး sum ကို output ပြပါ။"]] },
    "stdlib-system": { intro: "Time နှင့် system helpers များသည် Zap program ကို လက်ရှိ environment နှင့် ချိတ်ဆက်ပေးသည်။", blocks: [["အချိန်ရယူခြင်း", "now ဖြင့် လက်ရှိအချိန် value ကို ရယူပြီး timestamp အဖြစ် သိမ်းနိုင်သည်။", "let started = now()\nsay started"], ["Environment variable", "env မခေါ်မီ has_env ဖြင့် variable ရှိ/မရှိ စစ်ပါ။ မရှိသော config ကို ရှင်းလင်းစွာ ကိုင်တွယ်နိုင်သည်။", "if has_env(\"PATH\"):\n    say env(\"PATH\")"], ["လေ့ကျင့်ခန်း", "Environment variable တစ်ခုရှိမှသာ ၎င်း၏ value ကို output ပြသည့် program ရေးပါ။"]] },
    "type-narrowing": { intro: "Type narrowing သည် condition သို့မဟုတ် Result/Option စစ်ဆေးပြီးနောက် value ၏ type ပိုမိုတိကျလာကြောင်း checker ကို သိစေသည်။", blocks: [["Option ကို narrow လုပ်ခြင်း", "is_some စစ်ပြီးမှ unwrap ကို အသုံးပြုပါ။", "let value: option<text> = some(\"Zap\")\nif is_some(value):\n    say unwrap(value)"], ["Result ကို narrow လုပ်ခြင်း", "is_ok သို့မဟုတ် is_err စစ်ပြီးမှ သက်ဆိုင်ရာ operation ကို ပြုလုပ်ပါ။", "let result = ok(42)\nif is_ok(result):\n    say unwrap(result)"], ["လေ့ကျင့်ခန်း", "Option value ရှိလျှင် ၎င်းကို output ပြပြီး မရှိလျှင် default text ပြသည့် function ရေးပါ။"]] },
    deployment: { intro: "Deployment သည် စစ်ဆေးပြီးသား Zap project ကို မှန်ကန်သော native release နှင့် configuration ဖြင့် target environment သို့ ရွှေ့ခြင်းဖြစ်သည်။", blocks: [["မပို့မီ စစ်ဆေးရန်", "Zap version၊ OS၊ architecture၊ main file၊ modules၊ dependencies နှင့် environment variables များကို မှတ်တမ်းတင်ပါ။"], ["Binary ကိုက်ညီမှု", "Linux archive ကို Windows တွင် မသုံးပါနှင့်။ Official release ထဲမှ platform နှင့် architecture ကိုက်ညီသော asset ကို ရွေးပါ။", "zap --version\nzap check .\nzap build ."], ["လေ့ကျင့်ခန်း", "main.zp၊ module တစ်ခု၊ environment variable တစ်ခုနှင့် test command တစ်ခုပါသော project အတွက် deployment checklist ရေးပါ။"]] },
    "result-option": { intro: "Result နှင့် Option သည် အောင်မြင်မှု/အမှားနှင့် တန်ဖိုးရှိ/မရှိကို တိတိကျကျ ဖော်ပြသော wrapper type များဖြစ်သည်။ Error သို့မဟုတ် missing value ကို တိတ်တဆိတ် မဖုံးကွယ်ဘဲ caller က ကိုင်တွယ်နိုင်စေသည်။", blocks: [["Result အဓိပ္ပာယ်", "ok(value) သည် အောင်မြင်မှု၊ err(message) သည် အမှားကို ကိုယ်စားပြုသည်။ is_ok နှင့် is_err ဖြင့် အခြေအနေစစ်ပြီးမှ unwrap လုပ်ပါ။", "let success = ok(42)\nlet failure = err(\"မတွေ့ပါ\")\nsay is_ok(success)\nsay is_err(failure)"], ["Option အဓိပ္ပာယ်", "some(value) သည် value ရှိခြင်း၊ option_none() သည် value မရှိခြင်းကို ကိုယ်စားပြုသည်။ unwrap_or ဖြင့် fallback ထားနိုင်သည်။", "let present = some(\"Zap\")\nlet missing = option_none()\nsay unwrap_or(present, \"unknown\")\nsay unwrap_or(missing, \"unknown\")"], ["Propagation", "? operator သည် Result အောင်မြင်လျှင် value ကို ဆက်သုံးပြီး err ဖြစ်လျှင် လက်ရှိ function ထဲမှ error ကို ပြန်ပို့သည်။ Result မဟုတ်သော value ပေါ်တွင် ? သုံးခြင်းသည် မမှန်ပါ။", "fn profile(): result<text>:\n    let user = load_user()?\n    return ok(user)"], ["လေ့ကျင့်ခန်း", "Map key ရှိလျှင် ok ပြန်ပေးပြီး မရှိလျှင် err ပြန်ပေးသော lookup function ရေးပါ။"]] },
    errors: { intro: "Structured error သည် error အမျိုးအစား၊ message၊ file၊ line နှင့် column တို့ကို တည်ငြိမ်စွာ ထိန်းသိမ်းပေးသော diagnostic model ဖြစ်သည်။", blocks: [["Error raise", "raise သည် value တစ်ခုကို လက်ရှိ function နှင့် boundary များထဲမှ အပြင်သို့ ပို့သည်။", "fn load_config():\n    raise \"configuration unavailable\""], ["Try/catch", "try block မှ error ကို အဆင့်တူ catch binding ဖြင့် ဖမ်းပြီး ပြင်ဆင်နိုင်သည်။ catch variable သည် ထို block အတွင်းမှာသာ အသုံးပြုနိုင်သည်။", "try:\n    load_config()\ncatch error:\n    say \"handled: \" + error"], ["Diagnostic code", "SyntaxError၊ NameError၊ TypeError၊ FileNotFound နှင့် ProjectError ကဲ့သို့ stable kind/code များကို tooling က အသုံးပြုနိုင်သည်။ Secret များကို message ထဲ မထည့်ပါနှင့်။"], ["လေ့ကျင့်ခန်း", "code နှင့် message ပါသော map error တစ်ခု raise လုပ်ပြီး inner catch တွင် code၊ outer catch တွင် message ကို output ပြပါ။"]] },
    async: { intro: "Zap async runtime သည် deterministic single-threaded foundation ပေါ်တွင် async function၊ Future နှင့် await ကို ထိန်းချုပ်ထားသည်။ လက်ရှိ language-level evaluator သည် eager ဖြစ်ပြီး background thread အလိုအလျောက် မဖန်တီးပါ။", blocks: [["Async function", "fn ရှေ့တွင် async ထည့်ပြီး Future value ပြန်ပေးသော function ရေးနိုင်သည်။", "async fn answer() -> number:\n    return 42\n\nlet pending = answer()"], ["Await", "await သည် Future ထဲရှိ completed result ကို unwrap လုပ်သော expression ဖြစ်ပြီး assignment၊ return သို့မဟုတ် nested call ထဲတွင် သုံးနိုင်သည်။", "async fn load() -> number:\n    return 7\n\nlet value = await load()\nsay value + 1"], ["Task facade", "spawn သည် task future ပုံစံ value ဖန်တီးပြီး task_is_ready ဖြင့် ready ဖြစ်/မဖြစ် စစ်နိုင်သည်။ task_join သည် task ကို consume လုပ်ပြီး result ပြန်ပေးသည်။", "async fn answer() -> number:\n    return 42\n\nlet task = spawn(answer())\nsay task_is_ready(task)\nsay task_join(task)"], ["Cancellation နှင့် timeout", "Native runtime တွင် cancellation token၊ timeout_ticks၊ task limit နှင့် poll budget များရှိသည်။ ၎င်းတို့သည် deterministic ဖြစ်ပြီး arbitrary foreign blocking call ကို မဖြတ်တောက်နိုင်ပါ။"], ["လေ့ကျင့်ခန်း", "async function တစ်ခုရေး၊ await လုပ်၊ spawn ဖြင့် task ဖန်တီးပြီး ready နှင့် joined value ကို စစ်ပါ။"]] },
    defaults: { intro: "Default နှင့် named parameters သည် function ကို အသုံးပြုသူအတွက် ရှင်းလင်းစေပြီး ထပ်ခါတလဲလဲရေးရသော common value များကို လျှော့ချပေးသည်။", blocks: [["Default value", "Parameter နောက်တွင် = ဖြင့် default သတ်မှတ်ပါ။ Caller က မပေးလျှင် default ကို သုံးပြီး ပေးလျှင် override လုပ်သည်။", "fn greet(name: text = \"World\", punctuation: text = \"!\"):\n    return \"Hello, \" + name + punctuation\n\nsay greet()\nsay greet(\"Zap\", \".\")"], ["Required နှင့် optional", "Default မရှိသော required parameter ကို အမြဲပေးရသည်။ Default parameter ကို နောက်ဆုံးပိုင်းတွင် ထားလျှင် API ဖတ်ရလွယ်သည်။", "fn create_user(username: text, role: text = \"member\"):\n    return username + \" (\" + role + \")\n\nsay create_user(\"may\")"], ["Named argument", "Public API တွင် parameter name ကို တည်ငြိမ်အောင်ထားပြီး intent ရှင်းလင်းရန် named argument အသုံးပြုပါ။"], ["လေ့ကျင့်ခန်း", "required first name၊ optional title နှင့် punctuation ပါသော format_name function ရေးပြီး positional/named calls နှစ်မျိုး စမ်းပါ။"]] },
    diagnostics: { intro: "Diagnostics သည် CLI နှင့် LSP နှစ်ခုလုံးတွင် တူညီသော structured contract ကို အသုံးပြုသည်။ Machine-readable code နှင့် လူဖတ်ရန် message နှစ်မျိုးလုံးကို တည်ငြိမ်စွာ ထိန်းသိမ်းထားသည်။", blocks: [["Field များ", "code၊ kind၊ severity၊ file၊ line၊ column၊ message၊ notes နှင့် help တို့သည် diagnostic record ၏ အဓိက field များဖြစ်သည်။ CLI JSON သည် line/column ကို one-based ဖြင့် ထုတ်သည်။"], ["Stable code", "ZAP-SYNTAX-001၊ ZAP-NAME-001၊ ZAP-TYPE-001၊ ZAP-FILE-001 နှင့် ZAP-PROJECT-001 ကဲ့သို့ code များကို editor နှင့် CI က compatibility key အဖြစ် သုံးနိုင်သည်။", "zap check --json ."], ["LSP parity", "LSP diagnostic သည် range၊ severity၊ source၊ code နှင့် message ကို ထိန်းသိမ်းပြီး Zap-specific metadata ကို data object ထဲ ထည့်သည်။ CLI နှင့် editor rule တူညီရမည်။"], ["လုံခြုံရေး", "Secret၊ password နှင့် environment-specific path များကို diagnostic ထဲ မထည့်ပါနှင့်။ Message ပြောင်းလဲနိုင်သော်လည်း stable code ကို မတူညီသော error အတွက် ပြန်မသုံးပါနှင့်။"], ["လေ့ကျင့်ခန်း", "Type mismatch တစ်ခု ဖန်တီးပြီး zap check --json . မှ code၊ kind၊ line၊ message နှင့် help ကို ခွဲခြားရေးပါ။"]] },
    "typed-payloads": { intro: "Typed Result နှင့် Option payload များသည် success၊ failure၊ present နှင့် missing value တို့ သယ်ဆောင်မည့် type ကို ရှင်းလင်းစေသည်။", blocks: [["Result payload", "result<T> ဖြင့် success payload type ကို သတ်မှတ်နိုင်ပြီး error path ကိုလည်း အဓိပ္ပာယ်ရှိအောင် ထားရသည်။", "let answer: result<number> = ok(42)\nlet failure: result<text> = err(\"not found\")"], ["Option payload", "option<T> သည် value မရှိနိုင်သော်လည်း ရှိလာလျှင် type သတ်မှတ်ထားကြောင်း ဖော်ပြသည်။", "let user: option<text> = some(\"Zap\")\nlet missing: option<number> = option_none()"], ["Checker အကျိုး", "Boundary တွင် မကိုက်ညီသော value ကို အစောပိုင်းဖော်ထုတ်နိုင်ပြီး Result/Option wrapper နှင့် payload ကို မရောထွေးစေပါ။"], ["လေ့ကျင့်ခန်း", "Profile lookup အတွက် result<map> နှင့် optional score အတွက် option<number> ကြေညာပြီး success/missing နှစ်မျိုး စမ်းပါ။"]] },
    lsp: { intro: "Zap LSP သည် editor နှင့် language runtime ကြား JSON-RPC အခြေခံ feedback channel ဖြစ်ပြီး diagnostics၊ completion၊ hover၊ definition၊ workspace symbol နှင့် formatting ကို ပေးသည်။", blocks: [["LSP စတင်ခြင်း", "Terminal မှ zap lsp ကို run ပြီး editor သည် standard input/output မှတစ်ဆင့် Content-Length header ပါသော JSON-RPC message များ ပို့သည်။", "zap lsp"], ["Initialize နှင့် capabilities", "initialize message တွင် server information နှင့် text synchronization၊ completion၊ diagnostics၊ hover၊ definition၊ workspace-symbol capabilities များကို ကြေညာသည်။"], ["Document synchronization", "didOpen သည် document ကို သိမ်းပြီး diagnostics ထုတ်သည်။ didChange သည် source ကို အစားထိုးပြီး diagnostics အသစ် ထုတ်ပေးသည်။"], ["Completion နှင့် hover", "Completion သည် လက်ရှိ prefix အပေါ်မူတည်၍ keyword၊ top-level let နှင့် function declaration များကို filter လုပ်သည်။ Hover သည် parser-backed declaration metadata နှင့် source span ကို ပြသည်။"], ["Definition၊ symbol နှင့် formatting", "Definition သည် referenced declaration သို့ သွားစေပြီး workspace symbol သည် local import module များကို deterministic အတိုင်း ရှာသည်။ Formatting သည် line ending၊ tab၊ trailing space နှင့် final newline ကို normalize လုပ်သည်။"], ["လုံခြုံရေးနှင့် cross-check", "Local import များကို importing directory အတွင်းသာ ခွင့်ပြုပြီး traversal၊ မတွေ့သော၊ အရွယ်အစားကျော်သော module များကို ကျော်လွှားသည်။ Editor diagnostic ကို zap check --json . ဖြင့် ပြန်စစ်ပါ။", "zap check --json ."], ["လေ့ကျင့်ခန်း", "Type mismatch ပါသော .zp file တစ်ခုကို editor တွင်ဖွင့်၊ diagnostic ကိုဖတ်၊ hover/completion ကို စမ်းပြီး CLI JSON output နှင့် code/range ကို နှိုင်းယှဉ်ပါ။"]] },
  };
  const englishReferenceContent: Record<string, Lesson> = {
    "language-spec": { intro: "The Language Specification is the precise reference for Zap grammar, values, types, control flow, and module semantics.", blocks: [["Grammar and blocks", "Zap uses a colon and indentation to define a block. The parser records source spans for statements, expressions, and declarations.", "if ready:\n    say \"go\""], ["Type rules", "Annotations create boundary contracts. The checker compares an expression type with the expected type before execution."], ["Practice", "Choose one function, module, and Result example from the syntax guide and describe its grammar, type rule, and runtime effect."]] },
    "memory-model": { intro: "The Memory Model explains object-field reads, mutation conflicts, borrowing boundaries, and structured runtime errors.", blocks: [["Read and mutate", "Finish an active field access before mutating the same object. Conflicting access should become a BorrowError diagnostic instead of an unexplained panic."], ["Safe access", "Keep read and write operations in separate statements so the ownership boundary is visible.", "let profile = {\"name\": \"Mya\"}\nlet name = profile.name\nprofile.name = \"May\"\nsay name"], ["Practice", "Compare a safe object update with a conflicting read/write example and record the checker result."]] },
    "stdlib-index": { intro: "The Standard Library Index groups Zap helpers for text, math, collections, filesystem, JSON, time, logging, and built-in operations.", blocks: [["Choose before reimplementing", "Search the standard library for an existing helper before writing a duplicate function."], ["Respect boundaries", "File, network, environment, and time helpers cross external boundaries, so include explicit error and resource-limit handling."], ["Practice", "Choose one helper for text cleanup, JSON reading, and current time; document input, output, and failure behavior."]] },
    "stdlib-filesystem": { intro: "Filesystem and JSON APIs teach safe path handling, bounded file access, JSON parsing, and explicit missing or permission errors.", blocks: [["Validate paths", "Do not trust user-provided paths. Handle absolute paths, traversal-like paths, missing files, and permissions deliberately."], ["Read and parse", "Keep file-read errors separate from JSON-parse errors so the caller knows which boundary failed.", "let text = read_file(\"config.json\")\nlet config = json_parse(text)"], ["Practice", "Design a loader that returns a default map for a missing file and a structured error for invalid JSON."]] },
    "type-conformance": { intro: "Type Conformance compares annotations, generic payloads, Result/Option wrappers, and implementation behavior across the language toolchain.", blocks: [["Expected and actual", "A useful diagnostic identifies both the expected type and the actual expression type."], ["Generic payloads", "Check the wrapper and payload independently.", "let result: result<number> = ok(42)\nlet missing: option<text> = option_none()"], ["Practice", "Create a conformance table covering input type, return type, success payload, error path, and editor diagnostic."]] },
    "core-architecture": { intro: "Core Architecture traces a Zap source file through parsing, checking, evaluation, the native runtime, the CLI, and LSP tooling.", blocks: [["Source to result", "The parser creates an AST, the checker validates names and types, and the runtime evaluates the validated program."], ["CLI and editor", "The CLI owns check/run/test workflows while LSP reuses the same diagnostic contract inside an editor."], ["Practice", "Draw the source flow from `zap check --json .` to the editor diagnostic view."]] },
    "package-guide": { intro: "The Package Guide covers manifests, modules, versions, dependencies, lockfiles, exports, and publishing workflows.", blocks: [["Manifest", "Keep package name, version, entry point, and supported Zap range explicit."], ["Public API", "Export only the functions and values intended for consumers.", "export fn greet(name):\n    return \"Hello, \" + name"], ["Practice", "Design a reusable math package with a manifest, public API, version, and supported Zap range."]] },
    "registry-auth": { intro: "Registry Authentication explains HTTPS transport, bearer credentials, trusted indexes, checksums, and safe secret handling.", blocks: [["Credential boundary", "Never place tokens in source files, logs, or public manifests. Use an environment or secret-manager boundary."], ["Verify responses", "Check HTTPS, authenticated access, index integrity, and artifact checksums before consuming a package."], ["Practice", "Write four steps for a registry client: credential input, request, response verification, and safe error output."]] },
    rollback: { intro: "The Rollback Runbook is a repeatable procedure for returning to a known-good Zap release after an installation or compatibility failure.", blocks: [["Detect", "Define triggers such as checksum mismatch, startup regression, or a breaking compatibility issue."], ["Restore and verify", "Select the previous stable tag and matching platform asset, then run a version check and smoke test."], ["Practice", "Write detect, stop, restore, verify, and communicate steps for a failed release."]] },
    compatibility: { intro: "Compatibility Change lessons explain how to document syntax, runtime, CLI, package, and editor changes with migration guidance.", blocks: [["Classify the change", "Separate additive features, behavior changes, deprecations, and breaking changes."], ["Write migration notes", "Show old behavior, new behavior, required code changes, and a rollback path."], ["Practice", "Create a before/after example and migration checklist for a changed function parameter."]] },
    "release-history": { intro: "Release History helps learners compare language, runtime, tooling, and compatibility changes across official Zap versions.", blocks: [["Identify the version", "Compare the installed version, documentation version, and official release tag before debugging behavior."], ["Use the changelog", "Look for user-visible features, fixes, breaking changes, and known limitations."], ["Practice", "Summarize three changes and one compatibility note from an official release entry."]] },
    "spec-ownership": { intro: "Spec Ownership maps language areas to their source of truth, maintainers, tests, and implementation context.", blocks: [["Find the source of truth", "Compare the relevant specification, test, runtime implementation, and release note instead of relying on one README."], ["Propose a change", "Include the owner area, compatibility impact, and test plan in a language change proposal."], ["Practice", "Map the specification, implementation, test, and documentation sources for Result/Option."]] },
    "project-roadmap": { intro: "The Project Roadmap groups Zap work across the stable core, async runtime, registry, LSP, cross-platform delivery, and ecosystem.", blocks: [["Stable core", "The parser, checker, native runtime, Result/Option model, and diagnostics form the learning foundation."], ["Read status carefully", "A roadmap item may not be a stable feature. Confirm the release tag and implementation status before relying on it."], ["Practice", "Classify one stable feature, one in-progress feature, and one future idea with an official source link for each."]] },
  };
